<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class DeliveryNoteLine extends Model {protected $fillable=['delivery_note_id','inventory_product_id','quantity']; public function delivery():BelongsTo{return $this->belongsTo(DeliveryNote::class,'delivery_note_id');} public function product():BelongsTo{return $this->belongsTo(InventoryProduct::class,'inventory_product_id');}}